sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {
    try {
        var sub = current.subject; // MSSFUNDS-4: get the subject
        var client = sub.substr(sub.indexOf("[") + 1, sub.indexOf(":") - sub.indexOf("[") - 1); //Extract Client from Subject
        var family = current.fund_family; //Fund Family
        var department = current.fund_department; // Department
        var slaTimeSub = sub.substr(sub.indexOf("[Cut Off") + 8, sub.indexOf("] Cash") - sub.indexOf("[Cut Off") - 8); // Exctract SLA time, +8 because of length of "[Cut Off"
        var createdTime = current.sys_created_on;
        var emailSubject = current.subject.toString();
        var subjectArray = [];
        subjectArray.push(client.toString());
        subjectArray.push(family.toString());
        subjectArray.push(department.toString());
        subjectArray.push(slaTimeSub.toString());
        subjectArray.push(createdTime.toString());
        subjectArray.push(emailSubject);
        var grMaster = new GlideRecord('x_hsb11_mss_fund_0_funds_master');
        grMaster.addQuery('fund_family', family);
        grMaster.query();
        if (grMaster.next()) {
            slaTime = new GlideDateTime(grMaster.sla_for_1st_chaser); //Take SLA for Chaser for respective fund family
            var today = new GlideDateTime();
            slaTime.setDisplayValue(today.getDate() + ' ' + slaTime.getTime().getByFormat("HH:mm: ss"));
            if (slaTime < today)
                slaTime.addDaysUTC(1); //if SLA time is passed then add one day

            gs.eventQueueScheduled('x_hsb11_mss_fund_0.send.SLA1stchaser.ema', current, subjectArray.toString(), current.body.toString(), slaTime); //MSSFUNDS-4: Schedule an event to send an chaser
        }
    } catch (e) {
        gs.info(" Unknown Exception Processing Funds Chaser Email Communication" + e);
    }

})(current, previous);
